#define CH32RV_PORT_COMMON_MASK_F 0x00000000u   /* port absent */
#define CH32RV_PORT_COMMON_MASK(port) ( \
    (port) == 0 ? CH32RV_PORT_COMMON_MASK_A : \
    (port) == 1 ? CH32RV_PORT_COMMON_MASK_B : \
    (port) == 2 ? CH32RV_PORT_COMMON_MASK_C : \
